from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel on a
    thread pool. Results are in input order, regardless of worker count
    or task completion order."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative_and_zero() -> None:
    assert parities([-3, -2, 0, -1]) == [1, 0, 0, 1]


def test_parities_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1, -big - 1]) == [0, 1, 1]


def test_parities_preserves_order_large_input() -> None:
    xs = list(range(-500, 1500))
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_order_non_uniform_pattern() -> None:
    xs = [1, 1, 0, 1, 0, 0, 0, 1, 1, 0, 1]
    assert parities(xs) == xs


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    parities(xs)
    assert xs == [5, 6, 7]


def test_parities_returns_new_list() -> None:
    xs = [0, 1]
    out = parities(xs)
    assert out is not xs
    assert out == [0, 1]


def test_parities_repeatable() -> None:
    xs = list(range(200))
    first = parities(xs)
    assert all(parities(xs) == first for _ in range(5))
